const express = require('express');
const jwt = require('jsonwebtoken');

const config = require('../config');

const router = express.Router();

// Very small in-memory user store for the prototype environment.
// In production this is backed by LDAP/SSO.
const USERS = [
  { id: 1, username: 'alice', password: 'password123', role: 'admin' },
  { id: 2, username: 'bob', password: 'hunter2', role: 'user' }
];

function findUser(username, password) {
  return USERS.find(
    (u) => u.username === username && u.password === password
  );
}

function authMiddleware(req, res, next) {
  const header = req.headers['authorization'];
  if (!header) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }
  const parts = header.split(' ');
  if (parts.length !== 2 || parts[0] !== 'Bearer') {
    return res.status(401).json({ error: 'Invalid Authorization header' });
  }
  try {
    const payload = jwt.verify(parts[1], config.JWT_SECRET);
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

router.post('/login', (req, res) => {
  const { username, password } = req.body || {};
  if (!username || !password) {
    return res.status(400).json({ error: 'username and password required' });
  }

  const user = findUser(username, password);
  if (!user) {
    return res.status(401).json({ error: 'invalid credentials' });
  }

  const token = jwt.sign(
    { sub: user.id, username: user.username, role: user.role },
    config.JWT_SECRET,
    { expiresIn: '30m' }
  );

  res.json({ token });
});

router.get('/profile', authMiddleware, (req, res) => {
  res.json({ user: req.user });
});

// Legacy API key based auth for older tools.
function apiKeyMiddleware(req, res, next) {
  const apiKey = req.query.key || req.headers['x-internal-key'];
  if (!apiKey || apiKey !== config.INTERNAL_API_KEY) {
    return res.status(401).json({ error: 'invalid api key' });
  }
  next();
}

router.get('/status', apiKeyMiddleware, (req, res) => {
  res.json({ status: 'ok', time: new Date().toISOString() });
});

module.exports = router;


